import{_ as e,o as r,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"requestAnimationFrame","description":"requestAnimationFrame 在这段行情 ‑ 刷新逻辑里的作用 特性 说明 对行情表格更新的好处 执行时机 requestAnimationFrame(rAF) 回调总是在 浏览器下一帧绘制之前 触发（16.6 ms≈60 fps）。 ► 把 一帧内 到来的多条 W。","frontmatter":{"title":"requestAnimationFrame","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","异步编程"],"description":"requestAnimationFrame 在这段行情 ‑ 刷新逻辑里的作用 特性 说明 对行情表格更新的好处 执行时机 requestAnimationFrame(rAF) 回调总是在 浏览器下一帧绘制之前 触发（16.6 ms≈60 fps）。 ► 把 一帧内 到来的多条 W。","sidebarWeight":100,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/11-异步编程/requestAnimationFrame/requestAnimationFrame.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/05-异步编程/requestAnimationFrame/requestAnimationFrame.md","filePath":"posts/JavaScript系统教程/05-异步编程/requestAnimationFrame/requestAnimationFrame.md"}'),o={name:"posts/JavaScript系统教程/05-异步编程/requestAnimationFrame/requestAnimationFrame.md"};function a(d,t,i,g,m,l){return r(),s("div",null,[...t[0]||(t[0]=[n('<div><h1 id="requestanimationframe" tabindex="-1">requestAnimationFrame <a class="header-anchor" href="#requestanimationframe" aria-label="Permalink to &quot;requestAnimationFrame&quot;">​</a></h1><blockquote><p>本节目标：理解“requestAnimationFrame”的核心思路，并能把它用于实际开发或面试表达。 <strong>requestAnimationFrame 在这段行情</strong>**‑**<strong>刷新逻辑里的作用</strong></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>说明</strong></td><td><strong>对行情表格更新的好处</strong></td></tr><tr><td><strong>执行时机</strong></td><td>requestAnimationFrame(rAF) 回调总是在 <strong>浏览器下一帧绘制之前</strong> 触发（16.6 ms≈60 fps）。</td><td>► 把 <em>一帧内</em> 到来的多条 WebSocket 数据 <strong>压缩为一次 DOM 更新</strong>。</td></tr><tr><td>► 避免短时间内多次 patch/DOM 重排，显著降低卡顿与 Layout Thrashing。</td><td></td><td></td></tr><tr><td><strong>节能暂停</strong></td><td>当页面切到后台 / tab 失焦，浏览器会 <strong>停止 rAF</strong> 调度；回到前台自动恢复。</td><td>► 后台时不刷帧、不消耗 CPU；前台恢复后第一帧再更新，数据仍保持最新。</td></tr><tr><td><strong>节流天然 60</strong> <strong>fps</strong></td><td>最多一帧一次；即使行情每毫秒一条，也只渲染 60 fps — 足够平滑。</td><td>► 不必手写节流 / 防抖；避免 setTimeout 引发的 <em>帧间抖动</em>。</td></tr></tbody></table><p><strong>是否“中断</strong>**‑**<strong>恢复”</strong> <strong>？</strong> 是的：当标签页被隐藏、系统进入低电量模式等，浏览器主动暂停 rAF 队列；重新可见后继续调度，这就是“自动中断‑自动恢复”。</p><p><strong>requestIdleCallback（rIC）与 rAF 的区别</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>对比项</strong></td><td><strong>requestAnimationFrame</strong></td><td><strong>requestIdleCallback</strong></td></tr><tr><td>触发时机</td><td><strong>渲染前</strong>（Paint 之前）</td><td><strong>渲染后、空闲片段</strong>（有 50 ms 预算时）</td></tr><tr><td>适合任务</td><td>影响布局、需要尽快显示的视觉更新</td><td>不影响首屏、可延后执行的“后台”任务（缓存计算、日志上报…）</td></tr><tr><td>在隐藏标签页</td><td>暂停</td><td>继续，但时间片不稳定，最低 1 fps</td></tr><tr><td>行情刷新是否合适</td><td>✅：需要及时展示价格</td><td>❌：可能被拖到最小空闲片段，导致价格延迟跳动</td></tr></tbody></table><p><strong>如果确实想用 rIC 执行「不重要的增量计算」</strong></p><p>ts 复制编辑 function scheduleIdleFlush() { requestIdleCallback(function idleCb(deadline) { while (deadline.timeRemaining() &gt; 0 &amp;&amp; queue.length) { consumeOneTask() } if (queue.length) requestIdleCallback(idleCb) // 还没做完继续 })} <strong>不建议</strong> 用来驱动闪烁价格，因为 rIC 可能数百毫秒后才触发，视觉不流畅。</p><p><strong>其他可选方案及示例代码</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>方案</strong></td><td><strong>代码片段</strong></td><td><strong>适用场景 &amp; 对比</strong></td></tr><tr><td><strong>setTimeout + throttle</strong></td><td>ts\\nconst flush = throttle(realFlush, 16);\\nws.onmessage = () =&gt; { queue.push(msg); flush(); }\\n</td><td>简单易懂；但 setTimeout 与渲染帧 <strong>不同步</strong>，可能卡在“半帧”造成掉帧；后台标签仍照常执行→浪费。</td></tr><tr><td><strong>MessageChannel 微任务批量</strong></td><td>ts\\nconst mc = new MessageChannel();\\nmc.port1.onmessage = flush;\\nfunction schedule(){ mc.port2.postMessage(null); }\\n</td><td>微任务优先级比 rAF 高，<strong>可能阻塞渲染</strong>；刷新频率无法随帧率自适应。</td></tr><tr><td><strong>Web Worker 汇总 → 主线程一次性 postMessage</strong></td><td>主线程只在 message 里 patch。</td><td>把计算移到 Worker，减轻主线程 CPU；仍需 rAF 或 throttle 保证渲染节奏。</td></tr><tr><td><strong>Vue 3 watchPostEffect + nextTick 批量</strong></td><td>对 reactive queue watch，在 nextTick 统一更新。</td><td>仍然有一帧多次 Rerender 的可能；需要额外节流。</td></tr></tbody></table><p><strong>小结与实战推荐</strong></p><ol><li><strong>行情闪烁/价格跳动</strong> 属于明显的视觉更新 → <strong>首选 requestAnimationFrame</strong>。</li><li>若有 <strong>重量级计算</strong>（指标统计、历史回放）可以放进 Web Worker + postMessage；主线程仍用 rAF 取结果、刷新 DOM。</li><li>requestIdleCallback 适合 “不展示也行” 的缓存逻辑，不适合实时价格。</li><li>只要保证 <strong>一帧一次</strong>、更新 diff 最小，即可在万行表格中保持流畅滚动。</li></ol></div>',1)])])}const p=e(o,[["render",a]]);export{h as __pageData,p as default};
